package push

import (
	"encoding/json"
	"io"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
)

func TestListApplications(t *testing.T) {
	var gotKey string
	mux := http.NewServeMux()
	mux.HandleFunc("/application", func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodGet {
			w.WriteHeader(http.StatusMethodNotAllowed)
			return
		}
		gotKey = r.Header.Get("X-Gotify-Key")
		_ = json.NewEncoder(w).Encode([]map[string]any{
			{
				"id":              2,
				"token":           "secret-app-token-should-not-leak",
				"name":            "Zebra",
				"description":     "last",
				"defaultPriority": 5,
			},
			{
				"id":              1,
				"token":           "other-secret",
				"name":            "Alpha",
				"description":     "first",
				"defaultPriority": 0,
			},
		})
	})
	srv := httptest.NewServer(mux)
	defer srv.Close()

	c := New()
	apps, err := c.ListApplications(srv.URL, "client-token-abc")
	if err != nil {
		t.Fatal(err)
	}
	if gotKey != "client-token-abc" {
		t.Fatalf("X-Gotify-Key=%q", gotKey)
	}
	if len(apps) != 2 {
		t.Fatalf("len=%d", len(apps))
	}
	if apps[0].Name != "Alpha" || apps[1].Name != "Zebra" {
		t.Fatalf("order: %#v", apps)
	}
	if apps[0].ID != 1 || apps[0].DefaultPriority != 0 {
		t.Fatalf("alpha=%#v", apps[0])
	}
	raw, err := json.Marshal(apps)
	if err != nil {
		t.Fatal(err)
	}
	if strings.Contains(string(raw), "secret") || strings.Contains(string(raw), "token") {
		t.Fatalf("token leaked in JSON: %s", raw)
	}
}

func TestSend(t *testing.T) {
	var gotKey string
	var gotBody map[string]any
	mux := http.NewServeMux()
	mux.HandleFunc("/message", func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost {
			w.WriteHeader(http.StatusMethodNotAllowed)
			return
		}
		gotKey = r.Header.Get("X-Gotify-Key")
		body, _ := io.ReadAll(r.Body)
		if err := json.Unmarshal(body, &gotBody); err != nil {
			t.Errorf("body: %v", err)
		}
		_ = json.NewEncoder(w).Encode(map[string]any{"id": 9})
	})
	srv := httptest.NewServer(mux)
	defer srv.Close()

	c := New()
	if err := c.Send(srv.URL, "app-token-xyz", "Hi", "Hello world", 4); err != nil {
		t.Fatal(err)
	}
	if gotKey != "app-token-xyz" {
		t.Fatalf("X-Gotify-Key=%q (must be app token)", gotKey)
	}
	if gotBody["title"] != "Hi" || gotBody["message"] != "Hello world" {
		t.Fatalf("body=%#v", gotBody)
	}
	prio, ok := gotBody["priority"].(float64)
	if !ok || int(prio) != 4 {
		t.Fatalf("priority=%#v", gotBody["priority"])
	}
}

func TestSendEmptyMessage(t *testing.T) {
	called := false
	mux := http.NewServeMux()
	mux.HandleFunc("/message", func(w http.ResponseWriter, r *http.Request) {
		called = true
		w.WriteHeader(http.StatusOK)
	})
	srv := httptest.NewServer(mux)
	defer srv.Close()

	c := New()
	err := c.Send(srv.URL, "app-token", "t", "   ", 0)
	if err == nil {
		t.Fatal("expected error for empty message")
	}
	if called {
		t.Fatal("must not call API for empty message")
	}
}

func TestSendUnauthorized(t *testing.T) {
	mux := http.NewServeMux()
	mux.HandleFunc("/message", func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(http.StatusUnauthorized)
		_, _ = w.Write([]byte(`{"error":"Unauthorized"}`))
	})
	srv := httptest.NewServer(mux)
	defer srv.Close()

	c := New()
	err := c.Send(srv.URL, "bad", "t", "msg", 0)
	if err == nil {
		t.Fatal("expected error")
	}
}

func TestApplicationToken(t *testing.T) {
	var gotKey string
	mux := http.NewServeMux()
	mux.HandleFunc("/application/7", func(w http.ResponseWriter, r *http.Request) {
		gotKey = r.Header.Get("X-Gotify-Key")
		_ = json.NewEncoder(w).Encode(map[string]any{
			"id":    7,
			"name":  "Demo",
			"token": "app-token-from-detail",
		})
	})
	srv := httptest.NewServer(mux)
	defer srv.Close()

	c := New()
	token, err := c.ApplicationToken(srv.URL, "client-tok", 7)
	if err != nil {
		t.Fatal(err)
	}
	if gotKey != "client-tok" {
		t.Fatalf("key=%q", gotKey)
	}
	if token != "app-token-from-detail" {
		t.Fatalf("token=%q", token)
	}
}

func TestApplicationTokenNotFound(t *testing.T) {
	mux := http.NewServeMux()
	mux.HandleFunc("/application/99", func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(http.StatusNotFound)
		_, _ = w.Write([]byte(`not found`))
	})
	srv := httptest.NewServer(mux)
	defer srv.Close()

	c := New()
	_, err := c.ApplicationToken(srv.URL, "client-tok", 99)
	if err == nil {
		t.Fatal("expected error")
	}
}

package push

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"sort"
	"strings"
	"time"
)

// Client talks to the Gotify HTTP API for listing apps and sending messages.
type Client struct {
	HTTP *http.Client
}

// New returns a Client with a default timeout.
func New() *Client {
	return &Client{
		HTTP: &http.Client{Timeout: 15 * time.Second},
	}
}

// Application is a Gotify application without its secret token.
type Application struct {
	ID              uint   `json:"id"`
	Name            string `json:"name"`
	Description     string `json:"description"`
	DefaultPriority int    `json:"defaultPriority"`
}

type applicationDetail struct {
	ID              uint   `json:"id"`
	Name            string `json:"name"`
	Description     string `json:"description"`
	DefaultPriority int    `json:"defaultPriority"`
	Token           string `json:"token"`
}

// ListApplications returns applications for the account, sorted by name.
// Tokens from the API response are omitted from the returned values.
func (c *Client) ListApplications(serverURL, clientToken string) ([]Application, error) {
	serverURL = strings.TrimRight(strings.TrimSpace(serverURL), "/")
	clientToken = strings.TrimSpace(clientToken)
	if serverURL == "" || clientToken == "" {
		return nil, fmt.Errorf("server URL and client token are required")
	}

	req, err := http.NewRequest(http.MethodGet, serverURL+"/application", nil)
	if err != nil {
		return nil, err
	}
	setClientAuth(req, clientToken)

	resp, err := c.HTTP.Do(req)
	if err != nil {
		return nil, fmt.Errorf("list applications failed: %w", err)
	}
	defer resp.Body.Close()
	body, _ := io.ReadAll(io.LimitReader(resp.Body, 1<<20))

	if resp.StatusCode != http.StatusOK {
		return nil, fmt.Errorf("list applications returned %s: %s", resp.Status, truncate(string(body), 200))
	}

	var details []applicationDetail
	if err := json.Unmarshal(body, &details); err != nil {
		return nil, fmt.Errorf("parse applications: %w", err)
	}

	out := make([]Application, 0, len(details))
	for _, d := range details {
		out = append(out, Application{
			ID:              d.ID,
			Name:            d.Name,
			Description:     d.Description,
			DefaultPriority: d.DefaultPriority,
		})
	}
	sort.Slice(out, func(i, j int) bool {
		return strings.ToLower(out[i].Name) < strings.ToLower(out[j].Name)
	})
	return out, nil
}

// ApplicationToken fetches the app token for the given application id.
func (c *Client) ApplicationToken(serverURL, clientToken string, appID uint) (string, error) {
	serverURL = strings.TrimRight(strings.TrimSpace(serverURL), "/")
	clientToken = strings.TrimSpace(clientToken)
	if serverURL == "" || clientToken == "" {
		return "", fmt.Errorf("server URL and client token are required")
	}
	if appID == 0 {
		return "", fmt.Errorf("application id is required")
	}

	req, err := http.NewRequest(http.MethodGet, fmt.Sprintf("%s/application/%d", serverURL, appID), nil)
	if err != nil {
		return "", err
	}
	setClientAuth(req, clientToken)

	resp, err := c.HTTP.Do(req)
	if err != nil {
		return "", fmt.Errorf("get application failed: %w", err)
	}
	defer resp.Body.Close()
	body, _ := io.ReadAll(io.LimitReader(resp.Body, 1<<20))

	switch resp.StatusCode {
	case http.StatusOK:
		var d applicationDetail
		if err := json.Unmarshal(body, &d); err != nil {
			return "", fmt.Errorf("parse application: %w", err)
		}
		if d.Token == "" {
			return "", fmt.Errorf("application has no token")
		}
		return d.Token, nil
	case http.StatusNotFound:
		return "", fmt.Errorf("application not found")
	case http.StatusUnauthorized, http.StatusForbidden:
		return "", fmt.Errorf("unauthorized")
	default:
		return "", fmt.Errorf("get application returned %s: %s", resp.Status, truncate(string(body), 200))
	}
}

// Send posts a message using an application token.
func (c *Client) Send(serverURL, appToken, title, message string, priority int) error {
	serverURL = strings.TrimRight(strings.TrimSpace(serverURL), "/")
	appToken = strings.TrimSpace(appToken)
	message = strings.TrimSpace(message)
	if serverURL == "" || appToken == "" {
		return fmt.Errorf("server URL and app token are required")
	}
	if message == "" {
		return fmt.Errorf("message is required")
	}

	payload, err := json.Marshal(map[string]any{
		"title":    title,
		"message":  message,
		"priority": priority,
	})
	if err != nil {
		return err
	}

	req, err := http.NewRequest(http.MethodPost, serverURL+"/message", bytes.NewReader(payload))
	if err != nil {
		return err
	}
	req.Header.Set("Content-Type", "application/json")
	req.Header.Set("Accept", "application/json")
	req.Header.Set("X-Gotify-Key", appToken)

	resp, err := c.HTTP.Do(req)
	if err != nil {
		return fmt.Errorf("send message failed: %w", err)
	}
	defer resp.Body.Close()
	body, _ := io.ReadAll(io.LimitReader(resp.Body, 1<<20))

	switch resp.StatusCode {
	case http.StatusOK:
		return nil
	case http.StatusUnauthorized, http.StatusForbidden:
		return fmt.Errorf("unauthorized")
	default:
		return fmt.Errorf("send message returned %s: %s", resp.Status, truncate(string(body), 200))
	}
}

func setClientAuth(req *http.Request, clientToken string) {
	req.Header.Set("Accept", "application/json")
	req.Header.Set("X-Gotify-Key", clientToken)
}

func truncate(s string, n int) string {
	s = strings.TrimSpace(s)
	if len(s) <= n {
		return s
	}
	return s[:n] + "…"
}

