func (a *App) LeaveNotificationHistory() {
	a.leaveOverlayView()
}

// ListApplications returns Gotify applications for the configured account (no tokens).
func (a *App) ListApplications() ([]push.Application, error) {
	a.mu.Lock()
	serverURL := a.cfg.ServerURL
	token := a.cfg.ClientToken
	configured := a.cfg.Configured()
	a.mu.Unlock()
	if !configured {
		return nil, fmt.Errorf("not configured")
	}
	return a.push.ListApplications(serverURL, token)
}

// SendApplicationMessage sends a push message to the given Gotify application.
// The app token is fetched server-side and never exposed to the frontend.
func (a *App) SendApplicationMessage(appID uint, title, message string, priority int) error {
	a.mu.Lock()
	serverURL := a.cfg.ServerURL
	clientToken := a.cfg.ClientToken
	configured := a.cfg.Configured()
	a.mu.Unlock()
	if !configured {
		return fmt.Errorf("not configured")
	}
	if appID == 0 {
		return fmt.Errorf("application is required")
	}
	if priority < 0 {
		priority = 0
	}
	if priority > 10 {
		priority = 10
	}
	appToken, err := a.push.ApplicationToken(serverURL, clientToken, appID)
	if err != nil {
		return err
	}
	applog.Printf("send message app=%d token=%s", appID, applog.TokenFingerprint(appToken))
	return a.push.Send(serverURL, appToken, title, message, priority)
}

// OpenSendMessage shows the window with the send-message view.
func (a *App) OpenSendMessage() {
	a.mu.Lock()
	a.view = "send"
	a.mu.Unlock()
	if a.ctx != nil {
		runtime.WindowShow(a.ctx)
		runtime.WindowUnminimise(a.ctx)
		runtime.EventsEmit(a.ctx, "show-send", nil)
	}
	a.emitStatus()
}

// LeaveSendMessage returns to the Gotify UI if configured, else setup.
func (a *App) LeaveSendMessage() {
	a.leaveOverlayView()
}

func (a *App) leaveOverlayView() {
	a.mu.Lock()
	if a.cfg.Configured() {
		a.view = "gotify"
	} else {
		a.view = "setup"
	}
	view := a.view
	a.mu.Unlock()
	if a.ctx != nil {
		if view == "gotify" {
			runtime.EventsEmit(a.ctx, "show-gotify", map[string]string{
				"token":  a.GetClientToken(),
				"uiPath": a.GetUIPath(),
			})
		} else {
			runtime.EventsEmit(a.ctx, "show-setup", nil)
		}
	}
	a.emitStatus()
}

